select.where:
del_flag = 0
and source_type = #{sourceType}
and source_id = #{sourceId}
and merchant_id = #{merchantId}
and member_id = #{memberId}
and status = #{status}

and platform_takeover_at is not null
and platform_takeover_at is null

mapper.select:

where del_flag = 0
  and (payout_status = 0 or (payout_status in (5, 6) and status = 1))
  and COALESCE(update_time, create_time) < DATE_SUB(now(), INTERVAL #{minutes} MINUTE)
  and id > #{afterId} and id <= #{maxId}
order by id asc limit #{limit}
